#include <iostream>
#include <string>

// =========================================
// Tương đương GradeBook.h (Giao diện / Header)
// =========================================
class GradeBook {
public:
    explicit GradeBook(std::string name); // Constructor prototype
    void setCourseName(std::string name); // Setter prototype
    std::string getCourseName() const;    // Getter prototype (const)
    void displayMessage() const;          // Display prototype (const)
private:
    std::string courseName;               // Private data member
};

// =========================================
// Tương đương GradeBook.cpp (Hiện thực / Implementation)
// =========================================
GradeBook::GradeBook(std::string name) 
    : courseName(name) {
    // Khởi tạo thông qua member initializer list
}

void GradeBook::setCourseName(std::string name) {
    courseName = name;
}

std::string GradeBook::getCourseName() const {
    return courseName;
}

void GradeBook::displayMessage() const {
    std::cout << "Welcome to the grade book for\n" 
              << getCourseName() << "!\n";
}

// =========================================
// Tương đương main.cpp (Client Code)
// =========================================
int main() {
    GradeBook myGradeBook("CS50 Introduction to Computer Science");
    myGradeBook.displayMessage();

    myGradeBook.setCourseName("CS106B Programming Abstractions");
    std::cout << "Updated Course: " << myGradeBook.getCourseName() << "\n";

    return 0;
}
